<?php defined('ABSPATH')||exit; function bluprint_banner_defaults(){ return [ 'enabled'=>1, 'eyebrow'=>'', 'title'=>'', 'description'=>'', 'button_text'=>'مشاهده محصولات', 'button_url'=>'', 'button_target'=>0, 'background_color'=>'#093FB9', 'shadow_color'=>'#FAF8F0', 'image_id'=>0, 'image_opacity'=>100 ]; } function bluprint_get_banner_data($id=1){ $all=get_option('bluprint_banners',[]); $key='banner_'.absint($id); $data=is_array($all)&&isset($all[$key])&&is_array($all[$key])?$all[$key]:[]; return wp_parse_args($data,bluprint_banner_defaults()); } function bluprint_sanitize_banners($input){ $input=is_array($input)?$input:[]; $defaults=bluprint_banner_defaults(); $output=[]; foreach($input as $key=>$banner){ if(!preg_match('/^banner_[1-9][0-9]*$/',(string)$key)||!is_array($banner))continue; $output[$key]=[ 'enabled'=>empty($banner['enabled'])?0:1, 'eyebrow'=>sanitize_text_field($banner['eyebrow']??''), 'title'=>sanitize_text_field($banner['title']??''), 'description'=>sanitize_textarea_field($banner['description']??''), 'button_text'=>sanitize_text_field($banner['button_text']??''), 'button_url'=>esc_url_raw(trim($banner['button_url']??'')), 'button_target'=>empty($banner['button_target'])?0:1, 'background_color'=>sanitize_hex_color($banner['background_color']??'')?:$defaults['background_color'], 'shadow_color'=>sanitize_hex_color($banner['shadow_color']??'')?:$defaults['shadow_color'], 'image_id'=>absint($banner['image_id']??0), 'image_opacity'=>min(100,max(0,absint($banner['image_opacity']??100))) ]; } return $output; } function bluprint_register_banner_settings(){ register_setting('bluprint_banners_group','bluprint_banners',[ 'type'=>'array', 'sanitize_callback'=>'bluprint_sanitize_banners', 'default'=>[] ]); } add_action('admin_init','bluprint_register_banner_settings'); function bluprint_add_banners_page(){ add_submenu_page('bluprint-settings','مدیریت بنرها','بنرها','edit_theme_options','bluprint-banners','bluprint_render_banners_page'); } add_action('admin_menu','bluprint_add_banners_page'); function bluprint_banner_admin_assets($hook){ if(!bluprint_is_admin_page('bluprint-banners'))return; wp_enqueue_media(); wp_enqueue_style('wp-color-picker'); wp_enqueue_script('wp-color-picker'); wp_add_inline_script('wp-color-picker'," jQuery(function($){ $('.bluprint-banner-color').wpColorPicker(); $('.bluprint-banner-image-select').on('click',function(e){ e.preventDefault(); const button=$(this),wrap=button.closest('.bluprint-banner-image'); const frame=wp.media({title:'انتخاب تصویر بنر',button:{text:'استفاده از تصویر'},multiple:false,library:{type:'image'}}); frame.on('select',function(){ const attachment=frame.state().get('selection').first().toJSON(); wrap.find('input[type=hidden]').val(attachment.id); wrap.find('img').attr('src',attachment.url).show(); wrap.find('.bluprint-banner-image-remove').show(); }); frame.open(); }); $('.bluprint-banner-image-remove').on('click',function(e){ e.preventDefault(); const wrap=$(this).closest('.bluprint-banner-image'); wrap.find('input[type=hidden]').val('0'); wrap.find('img').attr('src','').hide(); $(this).hide(); }); $('.bluprint-banner-opacity').on('input',function(){ $(this).next('.bluprint-banner-opacity-value').text($(this).val()+'%'); }); }); "); } add_action('admin_enqueue_scripts','bluprint_banner_admin_assets'); function bluprint_render_banners_page(){ if(!current_user_can('edit_theme_options'))return; $banner=bluprint_get_banner_data(1); $name='bluprint_banners[banner_1]'; $image_id=absint($banner['image_id']); $image_url=$image_id?wp_get_attachment_image_url($image_id,'medium'):''; ?> <div class="wrap"> <h1>مدیریت بنرها</h1> <form method="post" action="options.php"> <?php settings_fields('bluprint_banners_group'); ?> <h2>بنر ۱</h2> <table class="form-table" role="presentation"> <tr> <th scope="row">وضعیت</th> <td> <label> <input type="checkbox" name="<?php echo esc_attr($name); ?>[enabled]" value="1" <?php checked($banner['enabled'],1); ?>> فعال‌سازی بنر </label> </td> </tr> <tr> <th scope="row"><label for="banner-1-eyebrow">عنوان کوچک</label></th> <td><input id="banner-1-eyebrow" class="regular-text" type="text" name="<?php echo esc_attr($name); ?>[eyebrow]" value="<?php echo esc_attr($banner['eyebrow']); ?>"></td> </tr> <tr> <th scope="row"><label for="banner-1-title">عنوان اصلی</label></th> <td><input id="banner-1-title" class="regular-text" type="text" name="<?php echo esc_attr($name); ?>[title]" value="<?php echo esc_attr($banner['title']); ?>"></td> </tr> <tr> <th scope="row"><label for="banner-1-description">توضیحات</label></th> <td><textarea id="banner-1-description" class="large-text" rows="3" name="<?php echo esc_attr($name); ?>[description]"><?php echo esc_textarea($banner['description']); ?></textarea></td> </tr> <tr> <th scope="row"><label for="banner-1-button-text">متن دکمه</label></th> <td><input id="banner-1-button-text" class="regular-text" type="text" name="<?php echo esc_attr($name); ?>[button_text]" value="<?php echo esc_attr($banner['button_text']); ?>"></td> </tr> <tr> <th scope="row"><label for="banner-1-button-url">لینک دکمه</label></th> <td><input id="banner-1-button-url" class="regular-text" type="url" dir="ltr" name="<?php echo esc_attr($name); ?>[button_url]" value="<?php echo esc_attr($banner['button_url']); ?>"></td> </tr> <tr> <th scope="row">باز شدن لینک</th> <td> <label> <input type="checkbox" name="<?php echo esc_attr($name); ?>[button_target]" value="1" <?php checked($banner['button_target'],1); ?>> باز شدن در تب جدید </label> </td> </tr> <tr> <th scope="row"><label for="banner-1-background">رنگ پس‌زمینه</label></th> <td><input id="banner-1-background" class="bluprint-banner-color" type="text" name="<?php echo esc_attr($name); ?>[background_color]" value="<?php echo esc_attr($banner['background_color']); ?>"></td> </tr> <tr> <th scope="row"><label for="banner-1-shadow">رنگ سایه</label></th> <td><input id="banner-1-shadow" class="bluprint-banner-color" type="text" name="<?php echo esc_attr($name); ?>[shadow_color]" value="<?php echo esc_attr($banner['shadow_color']); ?>"></td> </tr> <tr> <th scope="row">تصویر بنر</th> <td> <div class="bluprint-banner-image"> <input type="hidden" name="<?php echo esc_attr($name); ?>[image_id]" value="<?php echo esc_attr($image_id); ?>"> <img src="<?php echo esc_url($image_url); ?>" alt="" style="display:<?php echo $image_url?'block':'none'; ?>;max-width:320px;height:auto;margin-bottom:12px"> <p> <button type="button" class="button bluprint-banner-image-select">انتخاب تصویر</button> <button type="button" class="button bluprint-banner-image-remove" style="display:<?php echo $image_id?'inline-block':'none'; ?>">حذف تصویر انتخاب‌شده</button> </p> <p class="description">در صورت انتخاب نکردن تصویر، تصویر پیش‌فرض قالب استفاده می‌شود.</p> </div> </td> </tr> <tr> <th scope="row"><label for="banner-1-opacity">شفافیت تصویر</label></th> <td> <input id="banner-1-opacity" class="bluprint-banner-opacity" type="range" min="0" max="100" step="1" name="<?php echo esc_attr($name); ?>[image_opacity]" value="<?php echo esc_attr($banner['image_opacity']); ?>"> <strong class="bluprint-banner-opacity-value"><?php echo esc_html($banner['image_opacity']); ?>%</strong> </td> </tr> </table> <?php submit_button('ذخیره تنظیمات بنر'); ?> </form> </div> <?php }